Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
drm/amd/display: Fix a switch statement in
 populate_dml_output_cfg_from_stream_state()

It is likely that the statement related to 'dml_edp' is misplaced. So move
it in the correct "case SIGNAL_TYPE_EDP".

Fixes: 7966f319c66d ("drm/amd/display: Introduce DML2")
Signed-off-by: Christophe JAILLET <christophe.jaillet@wanadoo.fr>
Signed-off-by: Hamza Mahfooz <hamza.mahfooz@amd.com>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>

Here is the root cause:
The bug was caused by the incorrect placement of the assignment statement for `dml_edp` outside of the `SIGNAL_TYPE_EDP` case in a switch statement. This resulted in the `dml_edp` value not being assigned when the signal type was `EDP`, leading to potential misconfiguration of the output settings for EDP signals.

Here is the patch:

 static void populate_dml_output_cfg_from_stream_state(struct dml_output_cfg_st *out, unsigned int location,
 				const struct dc_stream_state *in, const struct pipe_ctx *pipe)
 {
 	unsigned int output_bpc;

 	out->DSCEnable[location] = (enum dml_dsc_enable)in->timing.flags.DSC;
 	out->OutputLinkDPLanes[location] = 4; // As per code in dcn20_resource.c
 	out->DSCInputBitPerComponent[location] = 12; // As per code in dcn20_resource.c

 	switch (in->signal) {
 	case SIGNAL_TYPE_DISPLAY_PORT_MST:
 	case SIGNAL_TYPE_DISPLAY_PORT:
 		out->OutputEncoder[location] = dml_dp;
 		if (is_dp2p0_output_encoder(pipe))
 			out->OutputEncoder[location] = dml_dp2p0;
 		break;
-		out->OutputEncoder[location] = dml_edp;
 	case SIGNAL_TYPE_EDP:
+		out->OutputEncoder[location] = dml_edp;
 		break;
 	case SIGNAL_TYPE_HDMI_TYPE_A:
 	case SIGNAL_TYPE_DVI_SINGLE_LINK:
 	case SIGNAL_TYPE_DVI_DUAL_LINK:
 		out->OutputEncoder[location] = dml_hdmi;
 		break;
 	default:
 		out->OutputEncoder[location] = dml_dp;
 	}

 	switch (in->timing.display_color_depth) {
 	case COLOR_DEPTH_666:
 		output_bpc = 6;
 		break;
 	case COLOR_DEPTH_888:
 		output_bpc = 8;
 		break;
 	case COLOR_DEPTH_101010:
 		output_bpc = 10;
 		break;
 	case COLOR_DEPTH_121212:
 		output_bpc = 12;
 		break;
 	case COLOR_DEPTH_141414:
 		output_bpc = 14;
 		break;
 	case COLOR_DEPTH_161616:
 		output_bpc = 16;
 		break;
 	case COLOR_DEPTH_999:
 		output_bpc = 9;
 		break;
 	case COLOR_DEPTH_111111:
 		output_bpc = 11;
 		break;
 	default:
 		output_bpc = 8;
 		break;
 	}

 	switch (in->timing.pixel_encoding) {
 	case PIXEL_ENCODING_RGB:
 	case PIXEL_ENCODING_YCBCR444:
 		out->OutputFormat[location] = dml_444;
 		out->OutputBpp[location] = (dml_float_t)output_bpc * 3;
 		break;
 	case PIXEL_ENCODING_YCBCR420:
 		out->OutputFormat[location] = dml_420;
 		out->OutputBpp[location] = (output_bpc * 3.0) / 2;
 		break;
 	case PIXEL_ENCODING_YCBCR422:
 		if (in->timing.flags.DSC && !in->timing.dsc_cfg.ycbcr422_simple)
 			out->OutputFormat[location] = dml_n422;
 		else
 			out->OutputFormat[location] = dml_s422;
 		out->OutputBpp[location] = (dml_float_t)output_bpc * 2;
 		break;
 	default:
 		out->OutputFormat[location] = dml_444;
 		out->OutputBpp[location] = (dml_float_t)output_bpc * 3;
 		break;
 	}

 	if (in->timing.flags.DSC) {
 		out->OutputBpp[location] = in->timing.dsc_cfg.bits_per_pixel / 16.0;
 	}

 	// This has been false throughout DCN32x development. If needed we can change this later on.
 	out->OutputMultistreamEn[location] = false;

 	switch (in->signal) {
 	case SIGNAL_TYPE_NONE:
 	case SIGNAL_TYPE_DVI_SINGLE_LINK:
 	case SIGNAL_TYPE_DVI_DUAL_LINK:
 	case SIGNAL_TYPE_HDMI_TYPE_A:
 	case SIGNAL_TYPE_LVDS:
 	case SIGNAL_TYPE_RGB:
 	case SIGNAL_TYPE_DISPLAY_PORT:
 	case SIGNAL_TYPE_DISPLAY_PORT_MST:
 	case SIGNAL_TYPE_EDP:
 	case SIGNAL_TYPE_VIRTUAL:
 	default:
 		out->OutputLinkDPRate[location] = dml_dp_rate_na;
 		break;
 	}

 	out->PixelClockBackEnd[location] = in->timing.pix_clk_100hz / 10000.00;

 	out->AudioSampleLayout[location] = in->audio_info.modes->sample_size;
 	out->AudioSampleRate[location] = in->audio_info.modes->max_bit_rate;

 	out->OutputDisabled[location] = true;
 }



